window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING["lesson-10"]={
  version:2,title:"Vegetarian Diets in Infancy",chapter:10,duration:"115–140 minutes",
  outcomes:["Explain why infant vegetarian nutrition requires growth monitoring and pediatric guidance rather than adult diet rules.","Distinguish breast milk, commercial infant formula and ordinary plant beverages.","Recognize reliable B12, vitamin D, iron, iodine, fat and energy planning priorities.","Introduce complementary foods by developmental readiness, texture progression and allergen guidance.","Interpret growth as a trajectory while screening intake, feeding skill and medical causes of faltering growth.","Recognize why strict macrobiotic or very-low-fat infant patterns can fail even when they contain many whole foods.","Identify unsafe practices including homemade formula, whole nuts, honey, unpasteurized foods and routine juice."],
  modules:[
    {id:"milk-foundation",title:"Protect the milk-feeding foundation",summary:"Start with breast milk or suitable commercial infant formula and coordinate feeding support.",moments:[
      {id:"l10-m1",title:"Infants are small but nutritionally intense",highYield:"Rapid growth and small stomachs create high nutrient needs per kilogram and little room for low-energy, low-nutrient foods.",teaching:["During the first year, body weight, length, brain and organ systems grow rapidly. Infants require substantially more energy and many nutrients per kilogram than adults, but their stomach capacity is small. Feeding therefore needs to be frequent, energy-dense, developmentally appropriate and safe.","A well-planned vegetarian or vegan pattern can support growth, but the margin for error is narrow. Slow growth is not inevitable in vegan infants, yet restrictive patterns, diluted feeds, low energy density, unreliable B12 or inappropriate milk substitutes can produce serious harm. Growth should be plotted over time, not judged from one appearance or percentile."],keyPoints:["Rapid growth raises needs per kilogram.","Small stomachs require nutrient density.","Vegan growth failure is not inevitable.","Growth trend and feeding assessment belong together."],visual:{title:"Infant nutrition equation",kind:"map",items:[{label:"High demand",detail:"Rapid tissue and brain growth"},{label:"Small capacity",detail:"Limited stomach volume"},{label:"Frequent feeds",detail:"Repeated opportunities for intake"},{label:"Dense foods",detail:"Energy, fat, protein and micronutrients"},{label:"Monitor",detail:"Growth trend, development and feeding skill"}]},mnemonic:{title:"Small stomach, big job",cue:"Dense · frequent · monitored",explanation:"A simple cue for the first-year feeding context."},goodToKnow:"A lower percentile is not automatically a problem; crossing percentiles, faltering trajectory and clinical signs require assessment.",practiceConnection:"Use pediatric growth standards and coordinated care. Do not diagnose growth failure from a single weight or social-media comparison.",activity:{prompt:"Why can very bulky, low-fat infant diets be risky?",options:[{text:"They can fill a small stomach before enough energy and nutrients are consumed",correct:true,feedback:"Correct. High volume can displace needed energy."},{text:"Infants need no dietary fat",correct:false,feedback:"Fat is important for energy and development."},{text:"Fibre is the only nutrient infants need",correct:false,feedback:"Infants require a full range of nutrients."}]}} ,
      {id:"l10-m2",title:"Breast milk or commercial infant formula is the primary feed",highYield:"For young infants, ordinary cow's milk and plant beverages are not substitutes for breast milk or commercial infant formula; later transition timing is jurisdiction-specific.",teaching:["Breast milk is the biologic reference feed and changes over the course of lactation, but it does not automatically correct every maternal nutrient deficiency. Milk B12 and iodine can be low when maternal status is inadequate, and vitamin D supplementation guidance still applies. Feeding effectiveness, transfer and infant growth require observation.","When breast milk is unavailable or insufficient, use a regulated commercial infant formula appropriate to the infant and family. Standard formula is modified to meet infant nutrient and safety requirements; it is not simply cow's milk with butterfat removed. Soy-based commercial infant formula can be appropriate in selected situations under pediatric guidance. Homemade formula is unsafe.","In current Canadian guidance, pasteurized homogenized cow's milk may become the main milk source between 9 and 12 months once iron-rich foods are eaten regularly. Fortified soy beverage is not recommended as the main milk source before age two; a vegan child under two who is no longer breastfed may continue soy-based commercial infant formula with pediatric guidance."],keyPoints:["Breast milk is primary but not nutritionally invulnerable.","Commercial formula is regulated and specifically formulated.","Ordinary plant beverages are not infant formula.","Use current local transition guidance."],visual:{title:"Milk-feeding hierarchy",kind:"layers",items:[{label:"Breast milk",detail:"Primary feed with lactation and nutrient support"},{label:"Commercial infant formula",detail:"Regulated alternative or supplement"},{label:"Canadian transition",detail:"Homogenized cow's milk may begin at 9–12 months when iron-rich foods are established"},{label:"Plant beverages",detail:"Not infant formula; in Canada, not the main milk source before age two"}]},mnemonic:{title:"BF, not beverage",cue:"Breast milk or Formula",explanation:"For young infants, ordinary beverages do not replace breast milk or commercial formula."},goodToKnow:"Transition timing is jurisdiction-specific. Canadian guidance permits homogenized cow's milk at 9–12 months in the right feeding context and delays fortified soy beverage as the main milk source until age two.",practiceConnection:"Low wet diapers, lethargy, jaundice, poor transfer, persistent pain or faltering growth require lactation or pediatric assessment.",activity:{prompt:"What is an appropriate breast-milk alternative for a young infant?",options:[{text:"A suitable regulated commercial infant formula",correct:true,feedback:"Correct. It is designed to meet infant nutrition and safety standards."},{text:"Homemade evaporated-milk formula",correct:false,feedback:"Homemade formula can cause dangerous nutrient and electrolyte errors."},{text:"Ordinary oat beverage",correct:false,feedback:"Plant beverages are not infant formula."}]}}
    ]},
    {id:"complementary",title:"Introduce complementary foods by readiness",summary:"Use developmental signs, progressive textures and current allergen guidance rather than rushing or delaying indiscriminately.",moments:[
      {id:"l10-m3",title:"Around six months, readiness and nutrient need converge",highYield:"Complementary foods usually begin around six months when developmental readiness is present; 'as early as possible' is unsafe.",teaching:["Current guidance generally supports exclusive breast milk for about six months when possible, with complementary foods introduced around six months while breastfeeding continues. The older four-month exclusive-feeding statement in the supplied quiz is outdated. Calendar age is considered together with developmental readiness and pediatric guidance.","Readiness signs include good head and neck control, sitting with support or independently enough for safe feeding, bringing objects to the mouth and diminished tongue-thrust reflex. Complementary means added to breast milk or formula, not replacing it abruptly. Begin with nutrient-dense textures and advance rather than remaining on thin purées for too long."],keyPoints:["Complementary foods generally begin around six months.","Readiness matters alongside age.","Milk feeds remain important.","Textures should progress with skill."],visual:{title:"Readiness convergence",kind:"map",items:[{label:"Age",detail:"Around six months for most term infants"},{label:"Posture",detail:"Stable head/neck and supported sitting"},{label:"Oral skill",detail:"Accepts food and moves it back to swallow"},{label:"Interest",detail:"Reaches and brings objects to mouth"},{label:"Need",detail:"Iron and energy needs exceed milk alone"}]},mnemonic:{title:"SHIN",cue:"Sit · Head control · Interest · No tongue thrust",explanation:"A readiness cue, used with age and pediatric guidance."},goodToKnow:"Prematurity and developmental conditions can change timing and feeding support needs.",practiceConnection:"Coughing, recurrent choking, wet voice or respiratory illness with feeds requires swallowing assessment rather than repeated texture restriction alone.",activity:{prompt:"When should complementary foods usually begin for a healthy term infant?",options:[{text:"Around six months when developmental readiness is present",correct:true,feedback:"Correct. Timing combines age, readiness and individual guidance."},{text:"As early as possible regardless of readiness",correct:false,feedback:"Early feeding without readiness can be unsafe."},{text:"Only after all teeth erupt",correct:false,feedback:"Teeth are not required for appropriately textured complementary foods."}]}} ,
      {id:"l10-m4",title:"Allergen introduction and texture safety require precision",highYield:"Do not delay common allergens without a clinical reason; introduce age-appropriate forms while avoiding choking hazards.",teaching:["Current allergy-prevention guidance has moved away from routine delay of common allergens. When the infant is ready for complementary foods, allergenic foods can be introduced in safe forms according to local pediatric guidance, especially for infants with severe eczema or known allergy who may need a supervised plan.","Whole nuts, spoonfuls of thick nut butter, whole grapes, hard raw vegetables and similar shapes are choking hazards. Use smooth thinned nut or seed butter, finely ground foods and developmentally appropriate textures. Distinguish gagging—a protective learning response—from choking, which may be silent and requires immediate action."],keyPoints:["Routine allergen delay is outdated.","High-risk infants need individualized guidance.","Modify texture and shape to reduce choking risk.","Gagging and choking are different."],visual:{title:"Allergen introduction steps",kind:"sequence",items:[{label:"Ready",detail:"Infant is developmentally ready for solids"},{label:"Safe form",detail:"Smooth, thinned or finely ground texture"},{label:"One opportunity",detail:"Introduce when the infant is well and observable"},{label:"Repeat",detail:"Maintain tolerated foods in the pattern"},{label:"Escalate",detail:"Seek urgent help for breathing or circulation symptoms"}]},mnemonic:{title:"SAFE",cue:"Suitable texture · Age-ready · Follow guidance · Emergency signs",explanation:"A four-part allergen and texture check."},goodToKnow:"Food-allergy prevalence estimates change by definition and population; one old percentage should not drive feeding decisions.",practiceConnection:"Hives with breathing difficulty, repetitive vomiting, facial swelling, lethargy or collapse requires emergency care according to local protocols.",activity:{prompt:"How should peanut be introduced to a ready infant when appropriate?",options:[{text:"In a smooth, thinned, age-appropriate form following guidance",correct:true,feedback:"Correct. This supports exposure while reducing choking risk."},{text:"As whole peanuts",correct:false,feedback:"Whole nuts are a major choking hazard."},{text:"Delay until adolescence for every infant",correct:false,feedback:"Routine long delay is outdated."}]}}
    ]},
    {id:"nutrient-density",title:"Build nutrient-dense vegetarian complementary feeding",summary:"Prioritize iron, B12, energy, fat, protein and calcium/D without letting fibre crowd out intake.",moments:[
      {id:"l10-m5",title:"Iron-rich foods belong near the start",highYield:"Infant iron stores decline during the second half-year; offer iron-rich complementary foods regularly with vitamin C partners.",teaching:["Iron needs become difficult to meet from breast milk alone around the time complementary feeding begins. Vegetarian options include iron-fortified infant cereal, well-cooked mashed legumes, tofu and other age-appropriate foods. Pairing with vitamin-C-rich fruit or vegetables improves nonheme iron absorption.","High-fibre foods are nutritious but can be bulky. Use smooth or soft textures, adequate fat and appropriate portions. Tea is not an infant beverage and inhibits iron absorption. Pediatric assessment may include iron supplementation or laboratory testing depending on birth history, feeding pattern and local policy."],keyPoints:["Iron priority rises around six months.","Fortified cereal, legumes and tofu can contribute.","Vitamin C supports absorption.","Bulky fibre can displace energy."],visual:{title:"Iron-rich infant plate",kind:"map",items:[{label:"Iron anchor",detail:"Fortified infant cereal, lentil, bean or tofu"},{label:"Vitamin C",detail:"Soft fruit, pepper, broccoli or tomato in safe form"},{label:"Energy",detail:"Breast milk/formula plus grain, starch or fat"},{label:"Texture",detail:"Mashed, minced or finger-food form matched to skill"}]},mnemonic:{title:"I-C-E",cue:"Iron · C · Energy",explanation:"Three checks for a vegetarian complementary meal."},goodToKnow:"Low birth weight, prematurity and maternal iron status can change an infant's iron plan.",practiceConnection:"Pallor, lethargy, poor feeding or faltering growth needs assessment; do not diagnose iron deficiency from food intake alone.",activity:{prompt:"Which complementary meal best supports nonheme iron?",options:[{text:"Iron-fortified cereal with mashed berries",correct:true,feedback:"Correct. It pairs iron with vitamin C."},{text:"Black tea and rice crackers",correct:false,feedback:"Tea inhibits iron absorption and the meal is low in iron."},{text:"Fruit juice as the only food",correct:false,feedback:"Juice lacks the required nutrient density."}]}} ,
      {id:"l10-m6",title:"B12, vitamin D, iodine and fat cannot be left implicit",highYield:"A breastfed vegan infant's B12 safety depends on verified maternal status and the infant plan; deficiency can cause permanent neurologic harm.",teaching:["Infants have small B12 stores and rapid neurologic development. If maternal B12 status or milk B12 is inadequate, deficiency can develop quickly with developmental regression, hypotonia, feeding difficulty and brain injury. Prevention requires a reliable maternal source and infant supplementation or formula plan according to pediatric guidance—not seaweed or fermented-food folklore.","Vitamin D supplementation follows local pediatric guidance. Iodine depends on maternal intake, formula or later foods, and excess seaweed is unsafe. Fat supports energy density and development; include smooth nut/seed pastes, avocado and appropriate oils while continuing breast milk or formula. DHA planning depends on milk, formula and qualified advice."],keyPoints:["Infant B12 deficiency is a neurologic emergency risk.","Maternal and infant plans must both be verified.","Vitamin D follows pediatric policy.","Fat is essential for energy density and development."],visual:{title:"Four explicit infant safeguards",kind:"comparison",items:[{label:"B12",detail:"Verified maternal and infant source"},{label:"Vitamin D",detail:"Jurisdiction-specific infant supplement guidance"},{label:"Iodine",detail:"Measured maternal/formula source; avoid variable kelp"},{label:"Fat/DHA",detail:"Adequate fat plus milk/formula-specific omega-3 plan"}]},mnemonic:{title:"B-D-I-F",cue:"B12 · D · Iodine · Fat",explanation:"Four safeguards that should never be assumed from the word vegan."},goodToKnow:"Folate can improve the anemia of B12 deficiency while neurologic injury continues, including in infants.",practiceConnection:"Developmental regression, hypotonia, unusual sleepiness, poor feeding or loss of milestones requires urgent pediatric assessment.",activity:{prompt:"Which is a dependable infant B12 strategy?",options:[{text:"A verified maternal/infant supplement or commercial formula plan under pediatric guidance",correct:true,feedback:"Correct. It uses measured active B12."},{text:"A spoonful of spirulina",correct:false,feedback:"Spirulina is not a reliable active B12 source for infants."},{text:"Unwashed produce",correct:false,feedback:"Contamination is unpredictable and unsafe."}]}}
    ]},
    {id:"safety-transition",title:"Protect safety through the first-year transition",summary:"Use commercial products as intended, avoid high-risk foods and build a supported path beyond 12 months.",moments:[
      {id:"l10-m7",title:"Some foods and drinks do not belong in the first year",highYield:"No homemade formula, no routine juice and no honey before 12 months; ordinary plant beverages do not replace infant feeds and are not a main milk source before age two in Canadian guidance.",teaching:["Homemade formula recipes based on evaporated milk, plant beverages or kitchen ingredients can produce dangerous electrolyte, protein, micronutrient and contamination errors. Commercial infant formula is regulated; higher phosphorus or sodium is not a benefit for immature kidneys.","Routine juice is not needed for infants, even when pasteurized. Whole fruit in safe texture is preferable once complementary foods begin. Honey is avoided before 12 months because of infant botulism risk. Unpasteurized foods and choking hazards also require clear prevention."],keyPoints:["Homemade formula is unsafe.","Routine infant juice is unnecessary.","Avoid honey before 12 months.","Ordinary plant beverages do not replace infant feeds."],visual:{title:"First-year red-light list",kind:"map",items:[{label:"Homemade formula",detail:"Nutrient, electrolyte and contamination danger"},{label:"Honey",detail:"Botulism risk before 12 months"},{label:"Routine juice",detail:"Not needed; displaces nutrient-dense intake"},{label:"Unpasteurized food",detail:"Pathogen risk"},{label:"Choking shapes",detail:"Whole nuts, grapes, hard chunks and similar hazards"}]},mnemonic:{title:"H-H-J-C",cue:"Homemade formula · Honey · Juice · Choking",explanation:"Four first-year safety checks."},goodToKnow:"Pasteurization makes juice safer from pathogens but does not make juice necessary for an infant.",practiceConnection:"If formula access or affordability is the barrier, connect the family with health and social supports rather than improvising a recipe.",activity:{prompt:"Why is homemade infant formula unsafe?",options:[{text:"It can create dangerous nutrient, electrolyte and contamination errors",correct:true,feedback:"Correct. Commercial formula is tightly formulated and regulated."},{text:"It always contains too little water and nothing else matters",correct:false,feedback:"Multiple composition and safety failures are possible."},{text:"It is safer because it has more sodium",correct:false,feedback:"Excess sodium can be dangerous to infants."}]}} ,
      {id:"l10-m8",title:"The transition from late infancy through age two is individualized",highYield:"In Canada, fortified plant beverages are not recommended as the main milk source before age two; vegan children who are not breastfed may need soy-based commercial infant formula through this period.",teaching:["Family foods expand through late infancy while breast milk may continue and the milk plan is reviewed. Current Canadian guidance allows pasteurized homogenized cow's milk to become the main milk source from 9 to 12 months once iron-rich foods are eaten regularly. For a vegan child under two who is no longer breastfed, soy-based commercial infant formula—not an ordinary soy beverage—is the recommended milk substitute under pediatric guidance.","From age two, an unsweetened fortified soy beverage may serve as the main plant-based milk option when the whole diet supplies adequate energy, protein, fat and micronutrients. Other plant beverages can be much lower in protein and energy. Continue growth monitoring and deliberate B12, vitamin D, iodine, iron, calcium and essential-fat planning."],keyPoints:["Transition timing and product choice are jurisdiction-specific.","Canadian guidance delays plant beverages as the main milk source until age two.","Young children need energy and fat density.","Growth and nutrient planning continue."],visual:{title:"Late-infancy-to-two transition check",kind:"sequence",items:[{label:"Growth",detail:"Review trajectory and feeding skill"},{label:"Milk source",detail:"Breast milk, suitable formula, or age-appropriate local alternative"},{label:"Family foods",detail:"Protein anchors, grains/starches, produce and fat"},{label:"Safeguards",detail:"B12, D, iodine, iron and omega-3 plan"},{label:"Follow-up",detail:"Pediatric and nutrition review as needed"}]},mnemonic:{title:"GBFSF",cue:"Growth · Beverage · Family foods · Safeguards · Follow-up",explanation:"A transition checklist, not a product endorsement."},goodToKnow:"Plant beverage formulations and pediatric recommendations vary by country. In current Canadian guidance, fortified soy beverage can become a main milk source at age two, not at 12 months.",practiceConnection:"Do not use an ordinary plant beverage as a one-for-one infant or young-toddler milk replacement without pediatric review.",activity:{prompt:"What is the safest Canadian plan for a vegan child under two who is no longer breastfed?",options:[{text:"Continue a suitable soy-based commercial infant formula with pediatric guidance",correct:true,feedback:"Correct. Ordinary fortified soy beverage is not recommended as the main milk source before age two in Canada."},{text:"Use ordinary oat beverage as the sole milk source",correct:false,feedback:"It is not nutritionally equivalent to infant formula."},{text:"Use homemade formula",correct:false,feedback:"Homemade formula can cause dangerous nutrient and electrolyte errors."}]}}
    ]},
    {id:"monitoring",title:"Monitor growth, intake and feeding skill together",summary:"Use trajectory rather than appearance, protect energy density and escalate red flags before a restrictive pattern causes developmental harm.",moments:[
      {id:"l10-m9",title:"Growth is a trajectory, not a single percentile",highYield:"One measurement is a snapshot; serial weight, length and head-circumference patterns must be interpreted with gestational age, family pattern, intake, feeding skill and health.",teaching:["Plot accurate repeated measurements on the growth chart recommended in the jurisdiction and look at direction over time. A naturally small infant can track consistently and be well nourished, while a previously larger infant crossing major percentile channels may need assessment. Prematurity requires corrected-age interpretation for a period, and head growth adds information about neurodevelopment.","Growth faltering is a description, not a diagnosis. Possible contributors include insufficient milk transfer, formula preparation error, low-energy complementary foods, feeding or swallowing difficulty, vomiting, diarrhea, allergy, infection, cardiac or endocrine disease and food insecurity. Vegetarian status is one part of the history; do not blame the diet label or overlook an unsafe implementation."],keyPoints:["Serial measurements are more informative than one percentile.","Weight, length and head circumference provide different information.","Corrected age matters after prematurity.","Faltering growth requires dietary, feeding and medical assessment."],visual:{title:"Growth-assessment layers",kind:"layers",items:[{label:"Measure",detail:"Accurate weight, recumbent length and head circumference"},{label:"Plot",detail:"Appropriate chart, sex and corrected age when relevant"},{label:"Trend",detail:"Direction and velocity across repeated visits"},{label:"Explain",detail:"Milk transfer, intake, skill, symptoms, disease and access"},{label:"Act",detail:"Feeding support, nutrition plan, labs or medical work-up"}]},mnemonic:{title:"M-P-T-E-A",cue:"Measure · Plot · Trend · Explain · Act",explanation:"A growth chart starts the assessment; it does not finish it."},goodToKnow:"Visual appearance can miss early faltering growth, and a percentile alone does not diagnose malnutrition.",practiceConnection:"Urgent assessment is warranted for lethargy, dehydration, recurrent choking, breathing difficulty with feeds, developmental regression or rapid downward growth trajectory.",activity:{prompt:"What is the strongest evidence that an infant's growth needs assessment?",options:[{text:"A concerning change in serial growth trajectory plus feeding or clinical context",correct:true,feedback:"Correct. Trend and context are more informative than a single point."},{text:"Being below the 50th percentile once",correct:false,feedback:"Healthy infants occupy many percentiles; one measurement is not a diagnosis."},{text:"Following a vegetarian family pattern by itself",correct:false,feedback:"The implementation, growth and clinical context determine risk."}]}} ,
      {id:"l10-m10",title:"Whole-food purity can still be too dilute for an infant",highYield:"Strict macrobiotic, raw or very-low-fat complementary patterns can provide bulky fibre while falling short on energy, protein, B12, D, calcium, iron, zinc, iodine and essential fats.",teaching:["Infants cannot compensate for low energy density by eating adult-sized volumes. A bowl built mostly from watery vegetables and coarse whole grains may look wholesome but fill the stomach before enough energy, fat and protein are consumed. Historical macrobiotic infant cohorts showed growth and developmental problems with gaps in energy, protein, B12, vitamin D, calcium and riboflavin; iron deficiency occurred even when iron intake appeared high.","A safer vegetarian pattern uses breast milk or suitable commercial formula as the foundation, then adds iron-rich foods, protein anchors, adequate fat and developmentally appropriate textures. Fortified foods and measured supplements are tools, not philosophical failures. If family rules prohibit all reliable B12, vitamin D, iodine or energy-dense options, the plan is not nutritionally complete and requires immediate collaborative redesign."],keyPoints:["Infant stomach capacity limits compensation for bulky low-energy food.","Strict macrobiotic patterns have documented growth and nutrient risks.","Iron intake does not guarantee iron status.","Reliable fortified foods and supplements may be essential safeguards."],visual:{title:"Energy-density rescue",kind:"comparison",items:[{label:"Too dilute",detail:"Watery vegetables, thin cereal and low-fat broth dominate"},{label:"Add an anchor",detail:"Lentil, tofu, bean or fortified infant cereal"},{label:"Add energy",detail:"Appropriate oil, avocado or smooth nut/seed paste"},{label:"Add absorption help",detail:"Vitamin-C-rich produce with iron foods"},{label:"Protect milk",detail:"Continue breast milk or suitable commercial formula"}]},mnemonic:{title:"M-I-L-K + F-A-T",cue:"Milk foundation · Iron · Legume/protein · kcal density + Fortification · Appropriate texture · Tracking",explanation:"A quick check for a restrictive infant plan; it does not replace pediatric guidance."},goodToKnow:"The danger is not whole grains or vegetables themselves. It is a pattern whose bulk and restrictions remove energy density and reliable nutrient routes.",practiceConnection:"Respect the family's values, show the exact physiologic gap, offer acceptable fortified or supplemental options and document refusal when a serious infant risk remains.",activity:{prompt:"Why can a very high-fibre, very-low-fat infant diet impair growth?",options:[{text:"Bulky food can fill a small stomach before enough energy and nutrients are consumed",correct:true,feedback:"Correct. Nutrient density matters because infant capacity is limited."},{text:"Infants should never eat vegetables",correct:false,feedback:"Vegetables can be valuable when the total meal is nutrient- and energy-dense."},{text:"All whole grains are toxic",correct:false,feedback:"Whole grains are not the problem; balance, texture and density are."}]}}
    ]}
  ],
  caseStudy:{title:"A homemade formula emergency waiting to happen",scenario:"A family wants to feed a four-month-old homemade oat beverage formula with molasses and kelp because it is 'natural.' The breastfeeding parent follows a vegan diet but has no verified B12 source. The infant is sleepy and feeding less.",prompts:["Which practices are unsafe now?","Which infant and maternal symptoms require urgent assessment?","What regulated feeding options should be discussed with the pediatric team?","Which nutrient plans must be verified for both parent and infant?"],takeaway:"Infants cannot absorb the risk of improvised feeding. Use breast milk with supported lactation and nutrient planning or suitable commercial formula, and escalate lethargy or feeding decline urgently."},
  recap:["Infants have high nutrient needs and small stomachs.","Breast milk or suitable commercial infant formula is the primary feed for young infants; later transition timing is jurisdiction-specific.","Complementary foods generally begin around six months when readiness is present.","Common allergens should be introduced in safe forms according to current guidance rather than routinely delayed.","Iron-rich foods and vitamin C belong early in complementary feeding.","B12, vitamin D, iodine and fat need explicit plans.","Growth is interpreted as a serial trajectory with feeding and medical context.","Strict macrobiotic or very-low-fat infant patterns can be too bulky and nutrient-poor despite a whole-food appearance.","Homemade formula, honey, routine juice and choking hazards are unsafe first-year practices.","In Canada, ordinary plant beverages are not recommended as the main milk source before age two."],
  flashcards:[{front:"Primary feeds for young infants",back:"Breast milk and/or a suitable regulated commercial infant formula.",tag:"milk feeding"},{front:"Complementary feeding timing",back:"Generally around six months when developmental readiness is present.",tag:"solids"},{front:"SHIN readiness cue",back:"Sit, head control, interest and no strong tongue-thrust reflex.",tag:"solids"},{front:"Commercial soy infant formula",back:"A regulated formula that may be appropriate in selected situations under pediatric guidance.",tag:"formula"},{front:"Ordinary plant beverage",back:"Not infant formula; Canadian guidance says it should not be the main milk source before age two.",tag:"formula"},{front:"Infant iron anchors",back:"Iron-fortified infant cereal, well-cooked legumes and tofu in safe textures.",tag:"iron"},{front:"Infant B12 risk",back:"Small stores and rapid brain growth make deficiency potentially rapid and neurologically severe.",tag:"B12"},{front:"SAFE allergens",back:"Suitable texture, age-ready, follow guidance and know emergency signs.",tag:"allergy"},{front:"Choking hazards",back:"Whole nuts, whole grapes, hard chunks and thick spoonfuls of nut butter are examples.",tag:"safety"},{front:"Homemade formula",back:"Unsafe because of nutrient, electrolyte and contamination risks.",tag:"safety"},{front:"Honey",back:"Avoid before 12 months because of infant botulism risk.",tag:"safety"},{front:"Post-infancy beverage check",back:"Assess age, jurisdiction, protein, energy, fat, fortification and the full diet.",tag:"transition"},{front:"Growth trajectory",back:"Serial weight, length and head-circumference patterns interpreted with age, history and feeding context.",tag:"growth"},{front:"Growth faltering",back:"A description of concerning growth change that requires dietary, feeding and medical assessment—not a diagnosis by itself.",tag:"growth"},{front:"Restrictive infant risk",back:"Bulky low-fat patterns can displace energy and reliable B12, D, calcium, iron, iodine, zinc and essential-fat sources.",tag:"macrobiotic"}],
  practice:[{prompt:"Why do infants need nutrient-dense foods?",answer:"They have high needs per kilogram but small stomach capacity.",rationale:"Low-energy bulk can displace required nutrients.",tag:"foundation"},{prompt:"What are the primary feeds for young infants?",answer:"Breast milk and/or suitable commercial infant formula.",rationale:"Ordinary plant beverages are not formulated for infant needs.",tag:"milk feeding"},{prompt:"When do complementary foods generally begin?",answer:"Around six months when developmental readiness is present.",rationale:"Age and skill converge with rising nutrient needs.",tag:"solids"},{prompt:"Name three readiness signs.",answer:"Examples: stable head control, supported sitting, interest/reaching and diminished tongue thrust.",rationale:"Readiness reduces feeding risk.",tag:"solids"},{prompt:"How can peanut be offered safely to a ready infant?",answer:"As a smooth, thinned, age-appropriate preparation following allergen guidance.",rationale:"Whole nuts and thick spoonfuls are choking hazards.",tag:"allergy"},{prompt:"Give one infant iron meal.",answer:"Iron-fortified cereal with mashed berries, or lentils with a vitamin-C-rich vegetable.",rationale:"It combines iron with an absorption enhancer.",tag:"iron"},{prompt:"Why is infant B12 deficiency urgent?",answer:"Small stores and rapid brain development allow severe, potentially permanent neurologic injury.",rationale:"Prevention requires measured reliable sources.",tag:"B12"},{prompt:"Why is pasteurized juice still unnecessary for infants?",answer:"Pasteurization reduces pathogen risk but juice can displace nutrient-dense foods and offers little fibre.",rationale:"Safety and nutritional need are separate questions.",tag:"juice"},{prompt:"Why is homemade formula unsafe?",answer:"Its nutrient, electrolyte and microbiologic composition cannot be reliably controlled.",rationale:"Commercial formula is regulated for infant needs.",tag:"formula"},{prompt:"What should be reviewed before a plant beverage becomes a young child's staple?",answer:"Age, jurisdiction, growth, full dietary intake, protein, energy, fat, fortification and pediatric guidance.",rationale:"In Canada, ordinary plant beverages are not a main milk source before age two.",tag:"transition"},{prompt:"Why is one low growth-chart percentile not enough to diagnose malnutrition?",answer:"Healthy infants track at many percentiles; serial direction, measurement quality, age correction, feeding and health context are required.",rationale:"Trajectory is more informative than one snapshot.",tag:"growth"},{prompt:"Why is a strict macrobiotic infant menu a nutrition risk even when it contains whole foods?",answer:"High bulk and low energy/fat can displace calories and reliable B12, D, calcium, iron, iodine, zinc and essential-fat sources.",rationale:"Whole-food quality does not override infant stomach capacity and nutrient density.",tag:"macrobiotic"}],
  sources:[{title:"Health Canada · Infant nutrition",url:"https://www.canada.ca/en/health-canada/services/infant-care/infant-nutrition.html"},{title:"Health Canada · Nutrition for healthy term infants, 6–24 months",url:"https://www.canada.ca/en/health-canada/services/canada-food-guide/resources/nutrition-healthy-term-infants/nutrition-healthy-term-infants-recommendations-birth-six-months/6-24-months.html"},{title:"Health Canada · Nutrition for children and adolescents",url:"https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/advice-nutrition-different-life-stages/considerations-children-adolescents.html"},{title:"WHO · Child growth standards",url:"https://www.who.int/tools/child-growth-standards"},{title:"Systematic review · Vegetarian diets during complementary feeding",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9459879/"},{title:"NIH ODS · Vitamin B12",url:"https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"}]
};
